/**
 * fireyejsRunner — Token generation and infrastructure.
 *
 * bx-ua: Generated by bxUaGenerator.ts — a pure Node.js implementation
 *   that replicates the AWSC fireyejs.js token format without Playwright.
 *   Matches the real token: "231!" + base64(900 bytes) = 1204 chars.
 *
 * bx-pp: SHA-256 payload hash fallback (opcode 58 needs real AWSC).
 *
 * Cookie refresh: Playwright browser navigates chat.qwen.ai to refresh
 *   acw_tc and other WAF session cookies. This is the only remaining
 *   browser dependency — runs once per 30 min per account.
 */
import { resolve } from 'path';
import { getBxUaToken } from './bxUaGenerator.ts';
import { logStore } from './logStore.ts';
import { QWEN_API_BASE } from './qwen.ts';
import { tokenCache } from './tokenCache.ts';
import { existsSync } from 'fs';
import { connect } from 'puppeteer-real-browser';

// ─── Constants ───────────────────────────────────────────────────────────────

const BX_UA_TTL_MS = 15 * 60 * 1000; // 15 min
const DEFAULT_FIREYEJS_PATH = resolve(process.cwd(), 'fireyejs.js');

// ─── bx-ua generation ────────────────────────────────────────────────────────
// Pure Node.js via bxUaGenerator.ts — no browser needed.
// Token matches real AWSC fireyejs.js output format exactly.

/**
 * Generate (or retrieve cached) bx-ua token.
 *
 * @returns The bx-ua token string (e.g. "231!<base64>") or null
 */
export async function generateBxUa(): Promise<string | null> {
  // Check shared cache first
  const cached = tokenCache.get('bx-ua');
  if (cached) return cached;

  try {
    const token = getBxUaToken();

    if (token && token.startsWith('231!')) {
      tokenCache.set('bx-ua', token, BX_UA_TTL_MS);
      logStore.log('info', 'fireyejs', `bx-ua generated via bxUaGenerator (${token.length} chars, TTL ${BX_UA_TTL_MS / 60000} min)`);
      return token;
    }

    logStore.log('warn', 'fireyejs', 'bx-ua generated but invalid format');
    return null;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    logStore.log('error', 'fireyejs', `bx-ua generation failed: ${msg}`);
    return null;
  }
}

// ─── bx-pp generation (Phase C) ──────────────────────────────────────────────

/**
 * Generate a bx-pp per-request signature.
 *
 * bx-pp is normally generated by fireyejs opcode 58. Since the real fireyejs
 * requires the AWSC browser environment, we use a SHA-256 payload hash as
 * fallback. Testing confirmed this works: the models endpoint returned 200.
 *
 * TODO: reverse-engineer opcode 58 from fireyejs.js for bx-pp generation
 * that matches what the real browser produces.
 */
export async function generateBxPp(payload?: string): Promise<string | null> {
  // ponytail: hash fallback until opcode 58 reverse-engineered
  try {
    const data = new TextEncoder().encode(payload || Date.now().toString());
    const hash = await crypto.subtle.digest('SHA-256', data);
    const hashHex = Array.from(new Uint8Array(hash))
      .map((b) => b.toString(16).padStart(2, '0'))
      .join('')
      .slice(0, 32);
    logStore.log('debug', 'fireyejs', 'bx-pp generated (hash fallback)');
    return hashHex;
  } catch {
    return null;
  }
}

// ─── Cookie refresh via browser (puppeteer-real-browser) ─────────────────────
// NOTE: Sebelumnya pakai puppeteer-core headless → terdeteksi Alibaba WAF
// ("Cookie refresh failed"). Sekarang pakai puppeteer-real-browser: real Chrome
// window via Xvfb + rebrowser anti-detection patches — sama seperti apiku
// /api/solve/recaptcha-v2, yang terbukti lolos WAF chat.qwen.ai.

const CHROME_CANDIDATES = [
  process.env.CHROME_PATH,
  process.env.CHROME_BIN,
  '/home/agentuser/.cache/puppeteer/chrome/linux-148.0.7778.97/chrome-linux64/chrome',
  '/usr/local/bin/google-chrome-stable',
  '/usr/bin/google-chrome-stable',
  '/usr/bin/google-chrome',
  '/usr/bin/chromium',
  '/usr/bin/chromium-browser',
].filter((p): p is string => !!p);

function resolveChromePath(): string | null {
  for (const p of CHROME_CANDIDATES) {
    try {
      if (existsSync(p)) return p;
    } catch {
      /* continue */
    }
  }
  return null;
}

let pptrBrowser: any = null;

async function getBrowser(): Promise<any> {
  if (pptrBrowser && (pptrBrowser as any).connected) {
    return pptrBrowser;
  }
  const chromePath = resolveChromePath();
  const { browser } = await connect({
    headless: false,
    turnstile: false,
    disableXvfb: false,
    // Pin binary Chrome (chrome-launcher) agar konsisten dgn apiku
    customConfig: chromePath ? { chromePath } : {},
    connectOption: {
      defaultViewport: { width: 1280, height: 720 },
      // Sebelumnya 300.000ms — kalau page hang, Runtime.callFunctionOn ikut
      // nunggu 5 menit → In-browser fetch failed (...Increase protocolTimeout)
      protocolTimeout: 60_000,
    },
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-dev-shm-usage',
      '--disable-gpu',
      '--disable-web-security',
      '--disable-blink-features=AutomationControlled',
    ],
  });
  pptrBrowser = browser;
  return pptrBrowser;
}

async function closeBrowser(): Promise<void> {
  if (pptrBrowser) {
    try {
      await pptrBrowser.close();
    } catch {
      // already closed
    }
    pptrBrowser = null;
  }
}

const COOKIE_REFRESH_TTL_MS = 30 * 60 * 1000; // 30 min

/**
 * Refresh cookies for an account by navigating chat.qwen.ai in a real Chrome.
 *
 * @param cookieStr - Current saved cookies (may be stale)
 * @returns Fresh cookie string or null
 */
export async function refreshCookiesViaBrowser(cookieStr: string): Promise<string | null> {
  let page: any = null;
  try {
    const browser = await getBrowser();
    page = await browser.newPage();
    await page.setUserAgent(
      'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/148.0.0.0 Safari/537.36',
    );

    if (cookieStr) {
      const cookies = cookieStr
        .split(';')
        .map((pair: string) => {
          const idx = pair.indexOf('=');
          if (idx <= 0) return null;
          const name = pair.slice(0, idx).trim();
          const value = pair.slice(idx + 1).trim();
          if (!name || !value) return null;
          return {
            name,
            value,
            domain: '.qwen.ai',
            path: '/',
            expires: Math.floor(Date.now() / 1000) + 3600,
            httpOnly: false,
            secure: true,
            sameSite: 'Lax' as const,
          };
        })
        .filter((c): c is NonNullable<typeof c> => c !== null);

      if (cookies.length) {
        await page.setCookie(...cookies).catch(() => {});
      }
    }

    await page.goto(QWEN_API_BASE, { waitUntil: 'domcontentloaded', timeout: 15_000 }).catch(() => {});
    // Wait for WAF challenge to resolve (maks 10s — kalau masih challenge
    // sesudah itu, probabilitas lolos kecil; fail cepat biar pool tidak numpuk)
    for (let i = 0; i < 10; i++) {
      const html = await page.evaluate(() => document.documentElement?.innerHTML || '').catch(() => '');
      if (!html.includes('aliyun_waf')) break;
      await new Promise((r) => setTimeout(r, 1000));
    }

    const freshCookies = await page.cookies();
    const cookieMap = new Map<string, string>();
    for (const c of freshCookies) {
      if (c.name && c.value) cookieMap.set(c.name, c.value);
    }

    const freshCookieStr = Array.from(cookieMap.entries())
      .map(([n, v]) => `${n}=${v}`)
      .join('; ');

    if (freshCookieStr) {
      logStore.log('info', 'fireyejs', `Cookies refreshed via Chrome: ${freshCookieStr.substring(0, 60)}...`);
      return freshCookieStr;
    }
    return null;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    logStore.log('warn', 'fireyejs', `Cookie refresh via browser failed: ${msg.substring(0, 100)}`);
    return null;
  } finally {
    if (page) {
      try {
        await page.close();
      } catch {
        /* ignore */
      }
    }
  }
}

// ─── In-browser fetch (apiku /api/solve/recaptcha-v2 approach) ───────────────
// Alibaba WAF mengikat challenge cookie (acw_sc__v2, ssxmod_itna2) ke TLS
// fingerprint browser yang menyelesaikan challenge. Jadi request API harus
// dikirim DARI browser yang sama (page.evaluate fetch), bukan dari worker HTTP
// terpisah (wreq-js). Ini persis cara apiku yang terbukti lolos WAF.

const IN_BROWSER_FETCH_TIMEOUT_MS = 25_000; // fail cepat — jangan sampai nge-hang 300s (Runtime.callFunctionOn)

const FORBIDDEN_HEADERS = new Set([
  'cookie', 'origin', 'referer', 'host', 'content-length',
  'connection', 'accept-encoding', 'user-agent', 'transfer-encoding',
  'keep-alive', 'upgrade', 'proxy-authorization', 'te', 'trailer',
]);

export interface InBrowserFetchResult {
  ok: boolean;
  status: number;
  text: string;
}

// ─── Circuit breaker in-browser fetch ───────────────────────────────────────
// Kalau jalur browser terus-menerus timeout, jangan coba lagi tiap request
// (tiap percobaan membuka Chrome + navigate 30s = makin menumpuk). Buka lagi
// otomatis setelah cooldown, supaya jalan lagi kalau WAF sudah sepi.

const CIRCUIT_BREAKER_THRESHOLD = 3;
const CIRCUIT_BREAKER_COOLDOWN_MS = 60_000;
let inBrowserStreak = 0;
let inBrowserOpenUntil = 0;

function circuitOpen(): boolean {
  return Date.now() < inBrowserOpenUntil;
}

export function resetInBrowserCircuit(): void {
  inBrowserStreak = 0;
  inBrowserOpenUntil = 0;
}

/**
 * Jalankan fetch ke endpoint Qwen dari dalam real Chrome (puppeteer-real-browser).
 *
 * @param url - URL endpoint lengkap (https://chat.qwen.ai/...)
 * @param options.cookieStr - Cookie akun (token + WAF cookies) utk di-set di browser
 * @returns { ok, status, text } atau null jika gagal
 */
export async function browserFetch(
  url: string,
  options: { method?: string; headers?: Record<string, string>; body?: string; cookieStr?: string } = {},
): Promise<InBrowserFetchResult | null> {
  // Circuit breaker: kalau jalur browser baru saja timeout berkali-kali,
  // lewati langsung (null) daripada buka Chrome lagi + menumpuk proses.
  if (circuitOpen()) {
    logStore.log('warn', 'fireyejs', `Circuit breaker ACTIVE — skip in-browser fetch to ${url.split('?')[0]}`);
    return null;
  }

  let page: any = null;
  try {
    const browser = await getBrowser();
    page = await browser.newPage();
    await page.setUserAgent(
      'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/148.0.0.0 Safari/537.36',
    );

    const cookieStr = options.cookieStr || '';
    if (cookieStr) {
      const cookies = cookieStr
        .split(';')
        .map((pair: string) => {
          const idx = pair.indexOf('=');
          if (idx <= 0) return null;
          const name = pair.slice(0, idx).trim();
          const value = pair.slice(idx + 1).trim();
          if (!name || !value) return null;
          return {
            name,
            value,
            domain: '.qwen.ai',
            path: '/',
            expires: Math.floor(Date.now() / 1000) + 86400,
            httpOnly: false,
            secure: true,
            sameSite: 'Lax' as const,
          };
        })
        .filter((c): c is NonNullable<typeof c> => c !== null);
      if (cookies.length) await page.setCookie(...cookies).catch(() => {});
    }

    // Muat app di browser agar challenge WAF terselesaikan (maks 15s)
    logStore.log('debug', 'fireyejs', `browserFetch step: goto ${url.split('?')[0]}`);
    const tGoto = Date.now();
    // networkidle0: tunggu sampai jaringan halaman benar2 diam — fetch in-page
    // ke chats/new menggantung selamanya kalau masih ada request SPA pending
    // (settings/update jalan tapi chats/new hang = page context belum stabil)
    await page.goto(`${QWEN_API_BASE}/`, { waitUntil: 'networkidle0', timeout: 15_000 }).catch(async () => {
      logStore.log('debug', 'fireyejs', `networkidle0 timeout — fallback domcontentloaded`);
      await page
        .goto(`${QWEN_API_BASE}/`, { waitUntil: 'domcontentloaded', timeout: 8_000 })
        .catch((e: any) => logStore.log('warn', 'fireyejs', `browserFetch goto failed: ${String(e).substring(0, 80)}`));
    });
    logStore.log('debug', 'fireyejs', `browserFetch step: goto done (${Date.now() - tGoto}ms)`);
    for (let i = 0; i < 10; i++) {
      const html = await page.evaluate(() => document.documentElement?.innerHTML || '').catch(() => '');
      if (!html.includes('aliyun_waf')) break;
      await new Promise((r) => setTimeout(r, 1000));
    }

    const { method = 'GET', headers = {}, body } = options;
    const safeHeaders: Record<string, string> = {};
    for (const [k, v] of Object.entries(headers)) {
      if (FORBIDDEN_HEADERS.has(k.toLowerCase())) continue;
      safeHeaders[k] = v;
    }
    // Buang header WAF-hygiene khusus yang mungkin di-strip/di-rebut page SPA
    // (qwen app memakai ulang header ini sendiri — duplikasi menimpa sehingga
    // fetch chats/new dengan cookie stale/diveto WAF → hang)
    delete safeHeaders['bx-v'];
    delete safeHeaders['bx-umidtoken'];
    delete safeHeaders['bx-pp'];
    delete safeHeaders['bx-et'];
    logStore.log('debug', 'fireyejs', `browserFetch step: evaluate start ${method} ${url.split('?')[0]}`);
    const tEval = Date.now();
    const evaluatePromise = page.evaluate(
      async ({ url, method, headers, body }: any) => {
        const ctrl = new AbortController();
        const timer = setTimeout(() => ctrl.abort(), 18_000);
        const marks: string[] = [];
        (window as any).__bfMarks = marks;
        const mark = (s: string) => {
          marks.push(s + '@' + (Date.now() % 1000000));
          (window as any).__bfLast = s;
        };
        try {
          mark('fetch-start');
          const res = await fetch(url, {
            method,
            headers,
            body,
            credentials: 'include',
            redirect: 'follow',
            signal: ctrl.signal,
          });
          mark('headers:' + res.status);
          const text = await res.text();
          mark('body-done');
          return { ok: res.ok, status: res.status, text, marks };
        } catch (e) {
          mark('catch:' + String(e));
          return { ok: false, status: 0, text: String(e), marks };
        } finally {
          clearTimeout(timer);
        }
      },
      { url, method, headers: safeHeaders, body },
    ).then((r: any) => {
      logStore.log('debug', 'fireyejs', `browserFetch step: evaluate done (${Date.now() - tEval}ms) marks=${JSON.stringify(r?.marks)}`);
      return r;
    });

    const raced = await Promise.race([
      evaluatePromise,
      new Promise<null>((resolve) =>
        setTimeout(() => resolve(null), IN_BROWSER_FETCH_TIMEOUT_MS),
      ),
    ]);

    if (raced === null) {
      // Baca stage terakhir di page sebelum dibuang — tahu persis hang di mana
      const lastMark = await page
        .evaluate(() => (window as any).__bfLast || (window as any).__bfMarks || 'no-mark')
        .catch(() => 'unreadable');
      logStore.log(
        'warn',
        'fireyejs',
        `In-browser fetch timed out after ${IN_BROWSER_FETCH_TIMEOUT_MS}ms — lastStage=${JSON.stringify(lastMark)} recycling browser`,
      );
      void closeBrowser().catch(() => {}); // buang page yang masih digantung
      inBrowserStreak++;
      if (inBrowserStreak >= CIRCUIT_BREAKER_THRESHOLD) {
        inBrowserOpenUntil = Date.now() + CIRCUIT_BREAKER_COOLDOWN_MS;
        logStore.log(
          'warn',
          'fireyejs',
          `Circuit breaker OPEN — in-browser fetch disabled for ${CIRCUIT_BREAKER_COOLDOWN_MS / 1000}s (` +
            `${inBrowserStreak}x timeout)`,
        );
      }
      return null;
    }

    inBrowserStreak = 0; // sukses → reset streak
    return raced as InBrowserFetchResult;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    logStore.log('warn', 'fireyejs', `In-browser fetch failed: ${msg.substring(0, 100)}`);
    inBrowserStreak++;
    if (inBrowserStreak >= CIRCUIT_BREAKER_THRESHOLD) {
      inBrowserOpenUntil = Date.now() + CIRCUIT_BREAKER_COOLDOWN_MS;
      logStore.log(
        'warn',
        'fireyejs',
        `Circuit breaker OPEN — in-browser fetch disabled for ${CIRCUIT_BREAKER_COOLDOWN_MS / 1000}s`,
      );
    }
    return null;
  } finally {
    if (page) {
      try {
        await page.close();
      } catch {
        /* ignore */
      }
    }
  }
}
